We consider $M$ trusted allies $\{\tf{X}_i\}_{i=1}^M\coloneqq
\{\tf{A}_a\}_{a\in\mathscr{A}}\cup\{\tf{B}_b\}_{b\in\mathscr{B}}\cup\{\tf{C}_c\}_{c\in\mathscr{C
}}$”.

Let $\Phi^{\operatorname{GHZ}}_{\vv{K}}$ denote $M$-partite GHZ state and $\Phi^+_{\vv{L}|\vv{A}}$ denote an Einstein–Podolsky–Rosen (EPR) state~\cite{EPR35}, also called a maximally entangled state, where maximal entanglement is between $\vv{L}$ and $\vv{A}$. It should be noted that $\Phi^+_{\vv{L}|\vv{A}}=\bigotimes_{a\in\msc{A}}\Phi^+_{L_a|A_a}$, where
\begin{equation}
    \Phi^+_{L_a|A_a}=\frac{1}{d}\sum_{i,j=0}^{d-1}\ket{i,i}\bra{j,j}_{L_aA_a}
\end{equation}
for an orthonormal basis $\{\ket{i}\}_{i}$, where $d=\min\{|L_a|,|A_a|\}$.

A measurement channel $\mc{M}_{A'\to AX}$ is a quantum instrument whose action is expressed as
\begin{equation}
    \mc{M}_{A'\to AX}(\cdot)=\sum_{x}\mathcal{E}^x_{A'\to A}(\cdot)\otimes\op{x}_X,
\end{equation}
where each $\mathcal{E}^x$ is a completely positive, trace non-increasing map such that $\mc{M}$ is a quantum channel and $X$ is a classical register that stores measurement outcomes.

A quantity is called a generalized divergence \cite{PV10,SW12} if it satisfies the following monotonicity (data-processing) inequality for all density operators $\rho$ and $\sigma$ and quantum channels $\mc{N}$:
\begin{equation} \mathbf{D}(\rho\Vert \sigma)\geq \mathbf{D}(\mathcal{N}(\rho)\Vert \mc{N}(\sigma)).
\end{equation}

Examples include the quantum relative entropy~\cite{Ume62} 
\begin{equation}
D(\rho\Vert\sigma)\coloneqq \operatorname{Tr}[\rho\log_2(\rho-\sigma)],
\end{equation}
for $\operatorname{supp}(\rho)\subseteq \operatorname{supp}(\sigma)$, otherwise it is $\infty$, as well as the sandwiched R\'enyi relative entropy  \cite{MDSFT13,WWY14} which is denoted as $\wt{D}_\alpha(\rho\Vert\sigma)$  and defined for states
$\rho,\sigma$, and  $\forall \alpha\in (0,1)\cup(1,\infty)$ as
\begin{equation} \wt{D}_\alpha(\rho\Vert \sigma):= \frac{1}{\alpha-1}\log_2 \operatorname{Tr}\left[\left(\sigma^{ (1-\alpha) / 2\alpha }\rho\sigma^{ (1-\alpha) / 2\alpha }\right)^\alpha \right] ,
\end{equation}
but it is set to $+\infty$ for $\alpha\in(1,\infty)$ if $\operatorname{supp}(\rho)\nsubseteq \operatorname{supp}(\sigma)$.

In the limit $\alpha\to 1$ the sandwiched R\'enyi relative entropy converges to the quantum relative entropy, in the limit  $\alpha\to \infty$, it converges to the max-relative entropy \cite{MDSFT13}, which is defined as \cite{D09,Dat09}
\begin{equation} D_{\max}(\rho\Vert\sigma)\coloneqq \inf\{\lambda\in\mathbb{R}:\ \rho \leq 2^\lambda\sigma\},
\end{equation}
and if $\operatorname{supp}(\rho)\nsubseteq\operatorname{supp}(\sigma)$ then $D_{\max}(\rho\Vert\sigma)=\infty$.

Another generalized divergence  is the $\varepsilon$-hypothesis-testing divergence \cite{BD10,WR12},  defined as
\begin{equation}
D^\varepsilon_h\!\(\rho\Vert\sigma\):=-\log_2\inf_{\Lambda: 0\leq\Lambda\leq \bbm{1}}\{\operatorname{Tr}[\Lambda\sigma]:\  \operatorname{Tr}[\Lambda\rho]\geq 1-\varepsilon\},
\end{equation}
for $\varepsilon\in[0,1]$ and density operators $\rho,\sigma$.

A state $\rho_{\vv{K}E}$ is called an $\varepsilon$-approximate conference key state, for $\varepsilon\in[0,1]$, if there exists a conference key state $\gamma^c_{\vv{K} E}$ such that~\cite{AH09}
\begin{equation}
F\(\gamma^c_{\vv{K} E},\rho_{\vv{K}E}\)\geq 1-\varepsilon. 
\end{equation}

Similar to a conference key state, a state $\rho_{\vv{SK}}$ is called an $\varepsilon$-approximate private state for $\varepsilon\in[0,1]$ if there exists a private state $\gamma_{\vv{SK}}$ such that~\cite{AH09} 
\begin{equation}
F\(\gamma_{\vv{SK}},\rho_{\vv{SK}}\)\geq 1-\varepsilon. 
\end{equation}

Any state extension (including purification) $\gamma_{\vv{SK}E}$ of such a private state \eqref{eq:multi-priv-state} necessarily has the following form~\cite{AH09}:
\begin{equation}
\gamma_{\vv{SK}E}\coloneqq U^{\text{tw}}_{\vv{SK}E} \(\Phi_{\vv{K}}\otimes\omega_{\vv{S}E}\) (U^{\text{tw}}_{\vv{SK}E})^\dag,
\end{equation}
where $\omega_{\vv{S}E}$ is a state extension of the density operator $\omega_{\vv{S}}$.

An arbitrary $n$-partite state is $m$-separable if it can be written as following convex composition:
\begin{equation}
\rho_{m-sep}=\sum_{x\in\msc{X}} p_X(x) \op{\psi^x_1}\otimes\op{\psi^x_2} \otimes...\otimes\op{\psi^x_m},
\end{equation}
where $p_X(x)$ is a probability distribution.

Let us first define the regularized relative entropy of entanglement of a multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ as
\begin{equation}
E^\infty_{R}(\mc{N}):=\inf_{\Lambda\in\operatorname{LOCC}}D^\infty(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}||\Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}),
\end{equation}
where $D^\infty(\mc{N}||\mc{M}):=\lim_{n\to\infty}\frac{1}{n}D(\mc{N}^{\otimes n}||\mc{M}^{\otimes n})$ and 
\begin{equation}
D(\mc{N}||\mc{M}):=\max_{\phi_{\vv{LA'}\vv{RB}\vv{P}}}D(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\phi)||\mc{M}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\phi)),
\end{equation}
where $L\simeq A'$, $R\simeq B$ and $P\simeq C$.

Then the following inequality holds
\begin{multline}
E_{E}(:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\rho)}\\ 
 \leq D\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{LA'}\vv{RB}\vv{P}})\Vert \Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\sigma'_{\vv{LA'}\vv{RB}\vv{P}}) \).
 \end{multline}

Applying the the chain rule from Ref.~\cite{fang2019chain}, we find that
\begin{align*}
&D\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{LA'}\vv{RB}\vv{P}})\Vert \Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\sigma'_{\vv{LA'}\vv{RB}\vv{P}}) \)\\
\leq&D\(\rho_{\vv{LA'}\vv{RB}\vv{P}}\Vert \sigma'_{\vv{LA'}\vv{RB}\vv{P}} \)\\ 
& +D^{\infty}\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\Vert \Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\).
\end{align*}

Since the above holds for arbitrary fully separable states $\sigma'_{\vv{LA'}\vv{RB}\vv{P}}$ and arbitrary LOCC channels $\Lambda_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$, we arrive at
\begin{multline}
E_{E}(:\vv{LA}:\vv{R}:\vv{PC}:)_{\mc{N}(\rho)}\\
 \leq  E_{E}(:\vv{LA'}:\vv{RB}:\vv{P}:)_{\rho}+ E^\infty_{E}(\mc{N}),
\end{multline}
finishing the proof.

The rate $P$ of a given $(n,K,\varepsilon)$ protocol is equal to the number of conference (secret) bits generated per channel use:
\begin{equation}
P\coloneqq \frac{1}{n}\log_2K. 
\end{equation}

The cppp-assisted secret-key-agreement capacity $\hat{P}_{\text{cppp}}$ of the channel $\mc{N}$ is always less than or equal to $\hat{P}_{\operatorname{LOCC}}$,
\begin{equation}
\hat{P}_{\text{cppp}}(\mc{N})\leq \hat{P}_{\operatorname{LOCC}}(\mc{N}). 
\end{equation}

\textit{Covariant channels}.--- For each $a\in\msc{A}$ and $b\in\msc{B}$, let $\msc{G}_a$ and $\msc{G}_b$ be finite groups of respective sizes $G_a$ and $G_b$ with respective unitary representations $g_a\rightarrow U_{A'_a}(g_a)$ and $g_b\rightarrow U_{B_b}(g_b)$ for all group elements $g_{a}$ and $g_{b}$. Let $W^{\vv{g}}_{A_a}$ and $W^{\vv{g}}_{C_c}$ be unitary representations for all $a\in\msc{A}$ and $c\in\msc{C}$, where $\vv{g}=\{g_a,g_b\}_{a,b}$. A multiplex quantum channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$ is \textit{covariant} with respect to these representations if the following relation holds for all input states $\rho_{\vv{A'}\vv{B}}$ and group elements $g_a\in\msc{G}_a$ and $g_b\in\msc{G}_b$ for all $a\in\msc{A}$ and $b\in\msc{B}$: 
\begin{align}
&\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}\(\(\bigotimes_{a\in\msc{A}}\mathcal{U}_{A'_a}^{g_a}\otimes\bigotimes_{b\in\msc{B}}\mathcal{U}_{B_b}^{g_b}\)(\rho_{\vv{A'}\vv{B}})\)\nonumber\\
&=\(\bigotimes_{a\in\msc{A}}\mathcal{W}_{A_a}^{\vv{g}}\otimes\bigotimes_{c\in\msc{C}}\mathcal{W}_{C_c}^{\vv{g}}\)\(\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}(\rho_{\vv{A'}\vv{B}})\),
\end{align}
where we have used the notation $\mc{U}(\cdot)\coloneqq U(\cdot)U^{\dag}$ for unitaries $U$.

In the case without error correction, we can define
\begin{equation}
{\mc N}_{AB\to XY}^{\text{repeater}}\coloneqq {\mc M}_{C_AC_B\to  XY}\circ {\mc N}_1^{A\to C_A}\otimes{\mc N}_2^{B\to C_B},
\end{equation}
where ${\mc M}_{C_AC_B\to XY}$ describes the measurement and sending of classical messages $X$ and $Y$ to Alice and Bob, respectively.

If we add one-way error correction, we get a bipartite channel of the form
\begin{equation}
{\mc N}_{A^kB^kX'Y'\to XY}^{\text{repeater}}\coloneqq {\mc M}_{\tilde{C}_A\tilde{C}_B\to  XY}\circ {\mc E}_1^{X'A^k\to \tilde{C}_A}\otimes{\mc E}_2^{Y'B^k\to \tilde{C}_B},
\end{equation}
where ${\mc E}_1^{A^k\to \tilde{C}_A}$ includes $k$ instances of the channel $ {\mc N}_1^{A\to C_A}$, the transmission of the classical data $X'$ obtained by Alice's part of the one-way error correction protocol to Charlie, as well as Charlie's part of the error correction protocol (Alice's part of the one-way error correction protocol is included in the LOCC). ${\mc E}_2^{Y'B^k\to \tilde{C}_B}$ is defined in the same way.

To calculate upper bound on the MDI-QKD capacity, it suffices to consider the relative entropy of entanglement of the Choi state of associated multiplex channel $\mathcal{N}^{\text{MDI},\mathcal{E}}_{\vv{A}\to \vv{Z}}$ as it is tele-covariant. Notice that the action of erasure channel $\mathcal{E}_{A_i\to C_i}$ on $D_i\in\{\op{H}_{A_i},\ket{H}\!\bra{V}_{A_i},\ket{V}\!\bra{H}_{A_i},\op{V}_{A_i}\}$ is given as
\begin{equation}
\mathcal{E}_{A_i\to C_i}(D_i)=\eta_iD_i+(1-\eta_i) \operatorname{Tr}[D_i]\op{e}_{C_i}.
\end{equation}
Then, the Choi state $J^\mathcal{E}_{\vv{L}\vv{C}}$ of $\bigotimes_{i=1}^2\mathcal{E}_{A_i\to C_i}$ is
\begin{equation}~ J^\mathcal{E}_{\vv{L}\vv{C}}=\bigotimes_{i=1}^2 \left(\eta_i\Phi^+_{L_iC_i}+ (1-\eta_i)\frac{\mathbbm{1}_{L_i}}{2}\otimes\op{e}_{C_i}\right). 
\end{equation}

For the bipartite MDI-QKD 
\begin{align}
    \mathcal{M}_{C_1C_2\to X}(\cdot) & =   q\sum_{j=1}^4\operatorname{Tr}[\Phi^{(j)}(\cdot)\Phi^{(j)}] \op{j}_X \nonumber \\ 
    &\qquad +(1-q)\operatorname{Tr}[\cdot]\otimes\op{\perp}_X, \end{align}
where $\{\Phi^{(j)}_{C_1C_2}\}_{j=1}^4$ is the Bell-measurement, a projective measurement. $\{\Phi^{(j)}_{C_1C_2}\}_{j=1}^4$ represents the set of maximally entangled states $\{\Phi^+,\Phi^-,\Psi^+,\Psi^-\}$ for two-qubit systems and $\ket{\perp}\perp\ket{j}$. We note that the Bell-measurement is tele-covariant. Upon action of the measurement channel $\mc{M}_{C_1C_2\to X}$ on the state $J^{\mathcal{E}}_{L_1L_2C_1C_2}$~(Eq. \eqref{eq:e-choi}), the output state is essentially of the form (see~Ref.~\cite{DKD18}) 
\begin{equation}
q\eta_1\eta_2\frac{1}{4} \sum_{j=1}^4 \Phi^{(j)}_{L_1L_2}\otimes\op{j}_X+(1-q\eta_1\eta_2)\frac{\mathbbm{1}_{L_1L_2}}{4}\otimes\op{\perp}_X. 
\end{equation}
This implies, the relative entropy of entanglement of the Choi state of $\mathcal{N}^{\text{MDI},\mathcal{E}}_{A_1A_2\to Z_1Z_2}$ is $q\eta_1\eta_2$.

Notice that the action of erasure channel $\mathcal{E}_{A_i\to C_i}$ on $D_i\in\{\op{H}_{A_i},\ket{H}\!\bra{V}_{A_i},\ket{V}\!\bra{H}_{A_i},\op{V}_{A_i}\}$ is given as
\begin{equation}
\mathcal{E}_{A_i\to C_i}(D_i)=\eta_iD_i+(1-\eta_i) \operatorname{Tr}[D_i]\op{e}_{C_i}.
\end{equation}

Then, the Choi state $J^\mathcal{E}_{\vv{L}\vv{C}}$ of $\bigotimes_{i=1}^2\mathcal{E}_{A_i\to C_i}$ is
\begin{equation}~ J^\mathcal{E}_{\vv{L}\vv{C}}=\bigotimes_{i=1}^2 \left(\eta_i\Phi^+_{L_iC_i}+ (1-\eta_i)\frac{\mathbbm{1}_{L_i}}{2}\otimes\op{e}_{C_i}\right). 
\end{equation}

For the bipartite MDI-QKD 
\begin{align}
    \mathcal{M}_{C_1C_2\to X}(\cdot) & =   q\sum_{j=1}^4\operatorname{Tr}[\Phi^{(j)}(\cdot)\Phi^{(j)}] \op{j}_X \nonumber \\ 
    &\qquad +(1-q)\operatorname{Tr}[\cdot]\otimes\op{\perp}_X, \end{align}
where $\{\Phi^{(j)}_{C_1C_2}\}_{j=1}^4$ is the Bell-measurement, a projective measurement. $\{\Phi^{(j)}_{C_1C_2}\}_{j=1}^4$ represents the set of maximally entangled states $\{\Phi^+,\Phi^-,\Psi^+,\Psi^-\}$ for two-qubit systems and $\ket{\perp}\perp\ket{j}$. We note that the Bell-measurement is tele-covariant.

Upon action of the measurement channel $\mc{M}_{C_1C_2\to X}$ on the state $J^{\mathcal{E}}_{L_1L_2C_1C_2}$~(Eq. \eqref{eq:e-choi}), the output state is essentially of the form (see~Ref.~\cite{DKD18}) 
\begin{equation}
q\eta_1\eta_2\frac{1}{4} \sum_{j=1}^4 \Phi^{(j)}_{L_1L_2}\otimes\op{j}_X+(1-q\eta_1\eta_2)\frac{\mathbbm{1}_{L_1L_2}}{4}\otimes\op{\perp}_X. 
\end{equation}

We begin with a fully separable pure state $\phi^n\in\operatorname{FS}\left(:\vv{A'^{ n}L}:\vv{B^{ n}R}:\vv{P}:\right)$. Here the notation $\vv{X^{ n}}$ means we consider $n$ copies of all subsystems $X_1,...,X_M$. Application of $n$ copies of the isometric extension of multiplex channel $\mc{N}_{\vv{A'B}\to\vv{AC}}$ results in a pure state $\psi^n_{:\vv{A^{ n}L}:\vv{R}:\vv{C^{ n}P}:E^{n}}$. Let us now choose one party, ${\bf X}_i$, $i\in\{1,...,M\}$ as the distributing party. Party ${\bf X}_i$ performs a POVM $\mc{Q}=\left\{Q_x\right\}$ with corresponding random variable $X=\{x,p(x)\}$ on her subsystem, resulting in a classical-quantum-...-quantum (c{\bf q}) state
\begin{equation}
\omega_{c{\bf q}}=\sum_xp(x)\op{x}_{X}\otimes\omega^x,
\end{equation}
where $\omega^x$ is the post measurement state of the remaining parties and Eve. Party ${\bf X}_i$ then processes $X$ using classical channels $X\to Y$ and $Y\to Z$, where $Y=\{y,q(y)\}$ and  $Z=\{z,r(z)\}$ are classical random variables. $Y$ is kept by party ${\bf X}_i$ (to be used for the key) and $Z$ is broadcasted to all other trusted parties (and Eve). Upon receiving $Z$, the other parties then perform their respective POVMs with the goal of estimating the key variable $Y$.

Party ${\bf X}_i$ performs a POVM $\mc{Q}=\left\{Q_x\right\}$ with corresponding random variable $X=\{x,p(x)\}$ on her subsystem, resulting in a classical-quantum-...-quantum (c{\bf q}) state
\begin{equation}
\omega_{c{\bf q}}=\sum_xp(x)\op{x}_{X}\otimes\omega^x,
\end{equation}
where $\omega^x$ is the post measurement state of the remaining parties and Eve.

Thus, as shown in Ref.~\cite{DW05}, every trusted party ${\bf X}_j$, where $i\neq j\in\{1,...,M\}$, obtains a common key with ${\bf X}$ at a rate $r_n^{i\to j}$ of 
\begin{equation} r_n^{i\to j}=\frac{1}{n}\(I(Y:{\bf X}_j|Z)_{\tilde{\omega}_{c{\bf q}}}-I(Y:E^n|Z)_{\tilde{\omega}_{c{\bf q}}}\),
\end{equation}
where in a slight abuse of notation we use ${\bf X}_j$ as a placeholder for $A^n_jL_j$, $R_j$ or $C^n_jP_j$, depending if ${\bf X}_j$ is in $\{{\bf A}_a\}_a$, $\{{\bf B}_b\}_b$ or $\{{\bf C}_c\}_c$, respectively. The second and third case corresponds of the reverse and direct scenarios in Ref.~\cite{pirandola2009direct}, respectively. Whereas,
\begin{equation}
\tilde{\omega}_{c{\bf q}}=\sum_{xyz}r(z|y)q(y|x)p(x)\op{xyz}\otimes\omega^x.
\end{equation}

Putting it all together, we can achieve the following rate of conference key:
\begin{equation}
\hat{P}_{\textnormal{cppp}}^{\mc{N}}\geq\max_i\min_j\lim_{n\to\infty}\max_{\substack{\phi^n,\mc{Q}\text{ POVM}\\X\to Y,Y\to Z} } r_n^{i\to j}, \end{equation}
with $\phi^n\in\operatorname{FS}\(:\vv{A'^{ n}L}:\vv{B^{ n}R}:\vv{P}:\)$.

We will now describe the protocol in detail: As before, we begin with a fully separable pure state $\phi^n\in\operatorname{FS}\(:\vv{A'^{ n}L}:\vv{B^{ n}R}:\vv{P}:\)$ and apply $n$ copies of the isometric extension of multiplex channel $\mc{N}_{\vv{A'B}\to\vv{AC}}$, resulting in a pure state $\psi^n_{:\vv{A^{ n}L}:\vv{R}:\vv{C^{ n}P}:E^{n}}$. 

Assume now we are given some permutation $\sigma:\{1,...,M\}\to\{\sigma(1),...,\sigma(M)\}$, which determines the order in which the parties participate in the protocol. Party ${\bf X}_{\sigma(1)}$ begins by performing a POVM $\mc{Q}^{(1)}$ on her share of $\psi^n$, i.e. on subsystem $A^n_{\sigma(1)}L_{\sigma(1)}$, $R_{\sigma(1)}$ or $C^n_{\sigma(1)}P_{\sigma(1)}$, depending on which kind of party ${\bf X}_{\sigma(1)}$ is. This results in a random variable $X^{(1)}=\{p_1(x_1),x_1\}$. The corresponding classical-quantum-...-quantum (c{\bf q}) state is
\begin{equation}
\omega^{(1)}_{c{\bf q}}=\sum_{x_1}p_1(x_1)\op{x_1}_{X^{(1)}}\otimes\omega^{x_1}.
\end{equation}
Party ${\bf X}_{\sigma(1)}$ then performs classical channels $X^{(1)}\to Y^{(1)}\to Z^{(1)}$, keeping random variable $Y^{(1)}$ and sending $Z^{(1)}$ to party ${\bf X}_{\sigma(2)}$. The corresponding c{\bf q} state is then given by 
\begin{equation} \tilde{\omega}^{(1)}_{c{\bf q}}=\sum_{x_1y_1z_1}r_1(z_1|y_1)q_1(y_1|x_1)p_1(x_1)\op{x_1y_1z_1}\otimes\omega^{x_1},
\end{equation}
where $\omega^{x_1}$ is the state of the remaining parties and Eve. Next, party ${\bf X}_{\sigma(2)}$ performs a POVM $\mc{Q}_{Z^{(1)}}^{(2)}$ on her share of $\omega^{x_{1}}$, which provides random variable ($X^{(2)}$. Party ${\bf X}_{\sigma(2)}$ then performs classical channels $Z^{(1)}X^{(2)}\to Y^{(2)}\to Z^{(2)}$, keeps $Y^{(2)}$ for herself and sends $Z^{(2)}$ to the next party ${\bf X}_{\sigma(3)}$, who applies the same procedure. The protocol is repeated until party ${\bf X}_{\sigma(M)}$ receives $Z^{(M-1)}$, followed by her POVM and post-processing. The c{\bf q} after $k\in\{1,...,M\}$ measurements and post-processing steps is given by
\begin{align} \tilde{\omega}^{(k)}_{c{\bf q}}=&\sum_{\substack{x_1...x_k\\y_1...y_k\\z_1...z_k}}\tilde{p}_{x_1y_1z_1...x_ky_kz_k}\\
&\times\op{x_1y_1z_1...x_ky_kz_k}\otimes\omega^{x_1...x_k},\nonumber
\end{align}
where we have defined recursively
\begin{align}
\tilde{p}_{x_1y_1z_1...x_ky_kz_k}=&r_k(z_k|y_k)q_k(y_k|x_kz_{k-1})p_k(x_k)\\
&\times\tilde{p}_{x_1y_1z_1...x_{k-1}y_{k-1}z_{k-1}}.\nonumber
\end{align}

Party ${\bf X}_{\sigma(1)}$ begins by performing a POVM $\mc{Q}^{(1)}$ on her share of $\psi^n$, i.e. on subsystem $A^n_{\sigma(1)}L_{\sigma(1)}$, $R_{\sigma(1)}$ or $C^n_{\sigma(1)}P_{\sigma(1)}$, depending on which kind of party ${\bf X}_{\sigma(1)}$ is. This results in a random variable $X^{(1)}=\{p_1(x_1),x_1\}$. The corresponding classical-quantum-...-quantum (c{\bf q}) state is
\begin{equation}
\omega^{(1)}_{c{\bf q}}=\sum_{x_1}p_1(x_1)\op{x_1}_{X^{(1)}}\otimes\omega^{x_1}.
\end{equation}

The c{\bf q} after $k\in\{1,...,M\}$ measurements and post-processing steps is given by
\begin{align} \tilde{\omega}^{(k)}_{c{\bf q}}=&\sum_{\substack{x_1...x_k\\y_1...y_k\\z_1...z_k}}\tilde{p}_{x_1y_1z_1...x_ky_kz_k}\\
&\times\op{x_1y_1z_1...x_ky_kz_k}\otimes\omega^{x_1...x_k},\nonumber
\end{align}
where we have defined recursively
\begin{align}
\tilde{p}_{x_1y_1z_1...x_ky_kz_k}=&r_k(z_k|y_k)q_k(y_k|x_kz_{k-1})p_k(x_k)\\
&\times\tilde{p}_{x_1y_1z_1...x_{k-1}y_{k-1}z_{k-1}}.\nonumber
\end{align}

Parties ${\bf X}_{\sigma(k)}$ and ${\bf X}_{\sigma(k+1)}$ can establish a key rate of \cite{DW05}

\begin{align}
r^{\sigma(k)\to\sigma(k+1)}=\frac{1}{n}&\(I(Y^{(k)}:{\bf X}_{\sigma(k+1)}|Z^{(k)})_{\tilde{\omega}^{(k)}_{c{\bf q}}}\right.\\\
&\left.-I(Y^{(k)}:E^n|Z^{(k)})_{\tilde{\omega}^{(k)}_{c{\bf q}}}\)\nonumber
\end{align}


We can again maximize over all free input states, POVMs as well as classical channels and consider the worst-case rate between any pair $({\bf X}_i,{\bf X}_j)$. Further we have the freedom to choose the order of the parties.

Putting it all together, we can achieve the following rate of conference key:
\begin{equation}
\hat{P}_{\textnormal{cppp}}^{\mc{N}}\geq\max_{\sigma\in\text{perm}}\min_k\lim_{n\to\infty}
\max_{\substack{\phi^n,\mc{Q}^{(1)},...,\mc{Q}^{(k)}\text{ POVM}\\X^{(1)}\to Y^{(1)}\to Z^{(1)},\\X^{(2)}Z^{(1)}\to Y^{(2)}\to Z^{(2)},\\...,\\X^{(k)}Z^{(k-1)}\to Y^{(k)}\to Z^{(k)}}} r^{\sigma(k)\to\sigma(k+1)}, \end{equation}
with $\phi^n\in\operatorname{FS}\(:\vv{A'^{ n}L}:\vv{B^{ n}R}:\vv{P}:\)$.

As a generalization of this idea, one easily comes up with the following lower bound, which is the main result of this section:
\begin{widetext}
 \begin{align}
    \hat{P}_{\textnormal{cppp}}^{\mc{N}}\geq\max_{T\subseteq G}\min_{t\in V_T,t'\in N[t]} \lim_{n\to\infty}
    \max_{\substack{\phi^n,\mc{Q}^{(1)},...,\mc{Q}^{(|V_T|)}\text{ POVM} \\X^{(v_1)}\to Y^{(v_1)}\to Z^{(v_1)},\\
        X^{(N[v_1])}Z^{(v_1)}\to Y^{(N[v_1])} \to (Z^{(N[v_1])})|_{\mbox{deg}\geq 2},\\
        X^{(N_2[v_1])}Z^{(N[v_1])} \to Y^{(N_2[v_1])}\to (Z^{(N_2[v_1])})|_{\mbox{deg}\geq 2},\\
            ...,\\
            X^{N_l[v_1]}Z^{N_l[v_1]} \to Y^{N_l[v_1]} 
        }}  r^{\sigma(t) \to \sigma(t')}, \end{align}
\end{widetext}
    where $1\leq l\leq n$ is an index that counts how many times the breadth-first search needs to be invoked in order to traverse all the edges of the spanning tree $T$.

The first inner maximization needs to be understood inductively. The first step is obvious:
    we begin with an arbitrary vertex  $v_1\in V_T$. The party $X_{v_1}$ who is at node $v_1$ performs a POVM $Q_{1}$
    which produces a random variable $X^{(v_1)}$. She processes this variable further to obtain $Y^{(v_1)}$
    and sends a communication in the form of a variable $Z^{(v_1)}$. The latter variable is broadcasted to all the next neighbors of $v_1$ i.e. $N[v_1] \setminus \{v_1\}$. Further, if at step $m-1$ the form of operations 
    and communication between the nodes has concise notation $X^{S_m}Z^{S_{m-1}}\rightarrow Y^{S_m} \rightarrow Z^{S_m}|_{\mbox{deg}\geq 2}$,
    then the next level of nesting i.e. 
    \begin{equation}
    X^{N[S_m]}Z^{S_{m}}\rightarrow Y^{N[S_m]} \rightarrow \left(Z^{N[S_m]}\right)|_{\mbox{deg}\geq 2}
    \end{equation}
    has to be understood as a short notation of the following postprocessing at a number of nodes
    from the set $N[S_m] = \{s_1,...,s_{r}\}$ with $r=|N[S_m]|$: 
    \begin{eqnarray}
    \forall_{s_i \in N[S_m]\,:\, \mbox{deg}(s_i)\geq 2}: \,X^{(s_i)} Z^{N[s_i]\cap p(s_i)} \rightarrow  Y^{(s_i)}\rightarrow Z^{(s_i)} \nonumber \\
    \forall_{s_i \in N[S_m]\,:\, \mbox{deg}(s_i)=1}: \,X^{(s_i)} Z^{N[s_i]\cap p(s_i)} \rightarrow  Y^{(s_i)}, \nonumber
    \end{eqnarray}

    where $p(s_i)$ denotes the parent vertex of the vertex $s_i$, that is the unique vertex belonging to the neighbourhood which is the closest to the root $v_1$ in terms of traversed edges.

Further, if at step $m-1$ the form of operations 
    and communication between the nodes has concise notation $X^{S_m}Z^{S_{m-1}}\rightarrow Y^{S_m} \rightarrow Z^{S_m}|_{\mbox{deg}\geq 2}$,
    then the next level of nesting i.e. 
    \begin{equation}
    X^{N[S_m]}Z^{S_{m}}\rightarrow Y^{N[S_m]} \rightarrow \left(Z^{N[S_m]}\right)|_{\mbox{deg}\geq 2}
    \end{equation}
    has to be understood as a short notation of the following postprocessing at a number of nodes
    from the set $N[S_m] = \{s_1,...,s_{r}\}$ with $r=|N[S_m]|$: 
    \begin{eqnarray}
    \forall_{s_i \in N[S_m]\,:\, \mbox{deg}(s_i)\geq 2}: \,X^{(s_i)} Z^{N[s_i]\cap p(s_i)} \rightarrow  Y^{(s_i)}\rightarrow Z^{(s_i)} \nonumber \\
    \forall_{s_i \in N[S_m]\,:\, \mbox{deg}(s_i)=1}: \,X^{(s_i)} Z^{N[s_i]\cap p(s_i)} \rightarrow  Y^{(s_i)}, \nonumber
    \end{eqnarray}

    where $p(s_i)$ denotes the parent vertex of the vertex $s_i$, that is the unique vertex belonging to the neighbourhood which is the closest to the root $v_1$ in terms of traversed edges.

An $(n,K,\varepsilon)$ LOCC conference key distillation begins with $M$ parties $\tf{A}_i$ for $i\in[M]$ sharing $n$ copies of $M$-partite quantum state $\rho_{\vv{A}}$, to which they apply an LOCC channel $\mathcal{L}_{\vv{A^{\otimes n}}\to \vv{SK}}$. The resulting output state satisfies the following condition:
\begin{equation}
    F(\mathcal{L}_{\vv{A^{\otimes n}}\to \vv{SK}}(\rho^{\otimes n}_{\vv{A}}), \gamma_{\vv{KS}})\geq 1-\varepsilon.
\end{equation}

We devise two families of biseparable states $\pi_\textnormal{W}^{n,M}$, $\pi_\textnormal{GHZ}^{n,M}$ adjusted to both number of copies $n$ and number of parties $M$.
\begin{align}
    &\pi_\textnormal{GHZ}^{n,M}:= \frac{1}{M}\sum_{i=1}^M \left ( \mathcal{S}_{1,i} \left( \frac{I}{2}\otimes \Phi_{M-1}^\mathrm{GHZ}\right)\right)^{\otimes n}, \\
    &\pi_\textnormal{W}^{n,M}:= \frac{1}{M}\sum_{i=1}^M \left ( \mathcal{S}_{1,i} \left( \op{0}\otimes \Phi_{M-1}^\mathrm{W}\right)\right)^{\otimes n}, \end{align}
where the operator $\mathcal{S}_{1,i}$ swaps the qubit of the first party with qubit of the $i$th party.

In the limit $\alpha\to 1/2$, the sandwiched R\'enyi relative entropy $\wt{D}_\alpha(\rho\Vert\sigma)$ converges to $-\log_2 F(\rho,\sigma)$, where $F(\rho,\sigma)$ is the fidelity between $\rho, \sigma$ and defined as
\begin{equation}
F(\rho,\sigma)\coloneqq \left[\operatorname{Tr}\left[\sqrt{\sqrt{\sigma}\rho\sqrt{\sigma}}\right]\right]^2.
\end{equation}

Recall the definition the twisting operation
\begin{equation}
U^\text{tw}_{\vv{KS}}=\sum_{i_1,...,i_M=0}^{K-1}\ket{i_1...i_M}\bra{i_1...i_M}_{\vv{K}}\otimes U_{\vv{S}}^{(i_1...i_M)}
\end{equation}
and a privacy test as
\begin{align}
\Pi^{\gamma,K}_{\vv{KS}}&=U^\text{tw}_{\vv{KS}}\(\Phi^{\operatorname{GHZ}}_{\vv{K}}\otimes\bbm{1}_{\vv{S}}\)U^{\text{tw}\dag}_{\vv{KS}}\\
&=\frac{1}{K}\sum_{i,k=0}^{K-1}\(\ket{i}\bra{k}\)^{\otimes M}_{\vv{K}}\otimes U_{\vv{S}}^{(i^M)}U_{\vv{S}}^{(k^M)\dag},
\end{align}
where we have defined the notation $i^M:=\underbrace{i...i}_{M\text{ times}}$.

Let us also define $m:=|I|$ and $n:=|J|$ and note that $M=m+n$. We can expand
\begin{align}
&\ket{\widetilde\varphi}_{S_{I}K_{I}}=\sum_{i_1,...,i_{m}=0}^{K-1}\widetilde{\alpha}_{i_1...i_{m}}\ket{i_1...i_{m}}_{K_{I}}\otimes\ket{\widetilde{\phi}_{i_1...i_{m}}}_{S_{I}}\\
&\ket{\overline\varphi}_{S_{J}K_{J}}=\sum_{j_1,...,j_{n}=0}^{K-1}\overline{\alpha}_{j_1...j_{n}}\ket{j_1...j_{n}}_{K_J}\otimes\ket{\overline{\phi}_{j_1...j_{n}}}_{S_J}.
\end{align}
Here $\widetilde{\alpha}_{i_1...i_{m}}\in\bbm{C}$ such that $\sum_{i_1,...,i_{m}=0}^{K-1}|\widetilde{\alpha}_{i_1...i_{m}}|^2=1$ and $\overline{\alpha}_{j_1...j_{n}}\in\bbm{C}$ such that $\sum_{j_1,...,j_{n}=0}^{K-1}|\overline{\alpha}_{j_1...j_{n}}|^2=1$.

Further it holds

\begin{widetext}
\begin{align}
\operatorname{Tr}\left[\Pi^{\gamma,K}_{\vv{KS}}\varphi_{\vv{KS}}\right]
&=\operatorname{Tr}\left[\(\frac{1}{K}\sum_{i,k=0}^{K-1}\(\ket{i}\bra{k}\)^{\otimes M}_{\vv{K}}\otimes U_{\vv{S}}^{(i^M)}U_{\vv{S}}^{(k^M)\dag}\)\widetilde\varphi_{K_IS_I}\otimes\overline\varphi_{K_JS_J}\right]\\
&=\frac{1}{K}\sum_{i,k=0}^{K-1}\widetilde{\alpha}_{i^{m}}\overline{\alpha}_{i^{n}}(\widetilde{\alpha}_{k^{m}})^*(\overline{\alpha}_{k^{n}})^*\operatorname{Tr}\left[U^{(i^M)\dag}\ket{\widetilde{\phi}_{i^m}}\bra{\widetilde{\phi}_{k^m}}_{S_I}\otimes\ket{\overline{\phi}_{i^n}}\bra{\overline{\phi}_{k^n}}_{S_J}U^{(k^M)}\right]\\
&=\frac{1}{K}\sum_{i,k=0}^{K-1}\widetilde{\alpha}_{i^m}\overline{\alpha}_{i^n}(\widetilde{\alpha}_{k^m})^*(\overline{\alpha}_{k^n})^*\bra{\zeta_k}\ket{\zeta_i}, \end{align}
\end{widetext}
where we have defined the state
\begin{equation}
\ket{\zeta_i}_{\vv{S}} \coloneqq U^{(i^M)\dag}\ket{\widetilde{\phi}_{i^m}}_{S_I}\otimes\ket{\overline{\phi}_{i^n}}_{S_J}.
\end{equation}

Let us consider any cppp-assisted protocol that achieves a rate $\hat{P}_{\textnormal{cppp}}^{\mc{N}}\equiv \hat{P}$. Let $\rho^{(1)}\in\operatorname{FS}(:\!\vv{LA'}\!:\!\vv{RB}\!:\!\vv{P}\!:)$ be a fully separable state generated by the first use of LOCC among all spatially separated allies. Let 
\begin{equation}
\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}}\coloneqq \mc{N}(\rho^{(1)}_{\vv{LA}\vv{RB}\vv{P}}).
\end{equation}

We note that $\tau^{(1)}$ is a separable state with respect to bipartition $\vv{LA}\vv{R}\vv{C}\!:\!\vv{P}$. The action of the decoder channel $\mc{D}\coloneqq \mc{L}^{(2)}_{\vv{LA}\vv{R}\vv{PC}\to \vv{SK}}$ on $\tau^{(1)}$ yields the state
\begin{equation}
\omega_{\vv{SK}}\coloneqq \mc{L}^{(2)}(\tau^{(1)}_{\vv{LA}\vv{R}\vv{PC}}).
\end{equation}

By assumption we have that
\begin{equation}
F(\gamma_{\vv{SK}}, \omega_{\vv{SK}})\geq 1-\varepsilon,
\end{equation}
for some ($M$-partite) private state $\gamma$. This implies that there exists a projector $\Pi^\gamma_{\vv{SK}}$ corresponding to a $\gamma$-privacy test such that (see Proposition~\ref{thm:priv-test})
\begin{equation}
\operatorname{Tr}[\Pi^\gamma_{\vv{SK}}\omega_{\vv{SK}}]\geq 1-\varepsilon. 
\end{equation}

From Theorem~\ref{thm:priv-gme},
\begin{equation}
\operatorname{Tr}[\Pi^\gamma_{\vv{SK}}\sigma'_{\vv{SK}}]\leq \frac{1}{K}=2^{-\hat{P}},
\end{equation}
for any $\sigma'\in\operatorname{BS}(:\!\vv{SK}\!:)$.

Since inequality \eqref{eq:one-shot-proof-part} also holds for an arbitrary $\sigma\in\operatorname{BS}(:\!\vv{LA}\!:\!\vv{R}\!:\vv{C}\!:)$, we can conclude that
\begin{equation}
\hat{P}\leq E^\varepsilon_{h,\operatorname{GE}}(\mc{N}).
\end{equation}

