Let $\epsilon>0$ and $n\in\mathbb{N}$. We begin by noting that in the case of teleportation-simulable multiplex channels LOCC-assistance does not enhance secret-key-agreement capacity, and the original protocol can be reduced to a cppp-assisted secret key agreement protocol \cite{PLOB15}. Namely, in every round $1\leq i \leq n$ it holds 
\begin{align}
\rho_i&=\mc{L}^i(\tau_i)=\mc{L}^i(\mc{N}_{\vv{{A'}^{(i-1)}}\vv{B^{(i-1)}}\to\vv{A^{(i-1)}}\vv{C^{(i-1)}}}(\rho_{i-1}))\\
&=\mc{L}^i(\mc{T}_{\vv{{A'}^{(i-1)}LA}\vv{B^{(i-1)}R}\vv{C}\to\vv{A^{(i-1)}}\vv{C^{(i-1)}}}(\theta_{\vv{LA}\vv{R}\vv{C}}\otimes\rho_{i-1})),
\end{align}
where $\mc{L}^i$ and $\mc{T}$ are LOCC.

As the initial state $\rho_0$ is assumed to be fully separable, we can get that the final state $\omega_{\vv{SK}}=\rho_n$ of an adaptive LOCC CKA-protocol involving $n$ uses of teleportation-simulable multiplex channel $\mc{N}_{\vv{A'}\vv{B}\to\vv{A}\vv{C}}$, can be expressed as
\begin{equation}
\omega_{\vv{SK}}=\mc{L}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}\to\vv{SK}}\(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\),
\end{equation}
where $\mc{L}$ is an LOCC operation with respect to the partition $:\vv{L^nA^n}:\vv{R^n}:\vv{C^n}:$.

As in the proof of Theorem \ref{theo:telecov-weakconv-GE} we have 
\begin{equation}
\omega_{\vv{SK}}=\mc{L}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}\to\vv{SK}}\(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\),
\end{equation}
where $\mc{L}$ is an LOCC operation with respect to the partition $:\vv{L^nA^n}:\vv{R^n}:\vv{C^n}:$. Now following the proof of Theorem \ref{thm:one-shot-cppp}, we have that
\begin{equation}
F(\gamma_{\vv{SK}}, \omega_{\vv{SK}})\geq 1-\varepsilon,
\end{equation}
for some private state $\gamma$, hence there exists a projector $\Pi^\gamma_{\vv{SK}}$ corresponding to a $\gamma$-privacy test such that (see Proposition~\ref{thm:priv-test})
\begin{equation}
\operatorname{Tr}[\Pi^\gamma_{\vv{SK}}\omega_{\vv{SK}}]\geq 1-\varepsilon. 
\end{equation}
On the other hand, from Theorem~\ref{thm:priv-gme}, we have
\begin{equation}
\operatorname{Tr}[\Pi^\gamma_{\vv{SK}}\sigma_{\vv{SK}}]\leq \frac{1}{K},
\end{equation}
for any $\sigma\in\operatorname{FS}(:\!\vv{SK}\!:)$. Let us suppose a state $\sigma'_{\vv{LA}\vv{R}\vv{C}}\in\operatorname{FS}(:\vv{LA}:\vv{R}:\vv{C}:)$ and let us define $\sigma_{\vv{SK}}=\mc{L}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}\to\vv{SK}}\({\sigma'}^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\)$, which is in $\operatorname{FS}(:\!\vv{SK}\!:)$. Hence for all $\alpha>1$ it holds,

\begin{align}
& \log_2 K\nonumber\\ 
&\leq D^\varepsilon_h\(\omega_{\vv{SK}}\Vert \sigma_{\vv{SK}}\)\\
&\leq D^\varepsilon_h\(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\Vert{\sigma'}^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\)\\
&\leq \widetilde{D}_\alpha\(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\Vert{\sigma'}^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\)+\frac{\alpha}{\alpha-1}\log_2\(\frac{1}{1-\epsilon}\)\\
&= n\widetilde{D}_\alpha\(\theta_{\vv{LA}\vv{R}\vv{C}}\Vert{\sigma'}_{\vv{LA}\vv{R}\vv{C}}\)+\frac{\alpha}{\alpha-1}\log_2\(\frac{1}{1-\epsilon}\)
\end{align}
The first inequality holds for any $\sigma\in\operatorname{FS}(\vv{SK})$. The second inequality follows from data processing inequality. The third inequality follows from eq. (\ref{eq:hyp-sand-rel}). The equality is due to the additivity of $\widetilde{D}_\alpha$ \cite{MDSFT13}. As the above holds for any $\sigma'_{\vv{LA}\vv{R}\vv{C}}\in\operatorname{FS}(:\vv{LA}:\vv{R}:\vv{C}:)$, we obtain Theorem~\ref{theo:E-alpha_bound}.

\qed

As in the proof of Theorem \ref{theo:telecov-weakconv-GE} we have 
\begin{equation}
\omega_{\vv{SK}}=\mc{L}_{\vv{L^nA^n}\vv{R^n}\vv{C^n}\to\vv{SK}}\(\theta^{\otimes n}_{\vv{LA}\vv{R}\vv{C}}\),
\end{equation}
where $\mc{L}$ is an LOCC operation with respect to the partition $:\vv{L^nA^n}:\vv{R^n}:\vv{C^n}:$.

Now following the proof of Theorem \ref{thm:one-shot-cppp}, we have that
\begin{equation}
F(\gamma_{\vv{SK}}, \omega_{\vv{SK}})\geq 1-\varepsilon,
\end{equation}
for some private state $\gamma$, hence there exists a projector $\Pi^\gamma_{\vv{SK}}$ corresponding to a $\gamma$-privacy test such that (see Proposition~\ref{thm:priv-test})
\begin{equation}
\operatorname{Tr}[\Pi^\gamma_{\vv{SK}}\omega_{\vv{SK}}]\geq 1-\varepsilon. 
\end{equation}

On the other hand, from Theorem~\ref{thm:priv-gme}, we have
\begin{equation}
\operatorname{Tr}[\Pi^\gamma_{\vv{SK}}\sigma_{\vv{SK}}]\leq \frac{1}{K},
\end{equation}
for any $\sigma\in\operatorname{FS}(:\!\vv{SK}\!:)$.

Following discussion in Section~\ref{sec:ex-mdi}, let us now consider MDI-QKD settings with noise model for transmission of qubit systems from both $\textbf{A}_{a_1}$ and $\textbf{A}_{a_2}$ to Charlie through qubit channels given by either depolarizing channel $\mc{D}^{l}_{A_i\to C_i}$ or dephasing channel $\mc{D}^s_{A_i\to C_i}$:
\begin{align}
   \mc{D}^l_{A_i\to C_i}(\rho_{A_i}) &= \lambda_{l}\rho_{C_i}+\frac{1-\lambda_l}{2}\bbm{1}_{C_i}, \\
    \mc{D}^s_{A_i\to C_i}(\rho_{A_i}) &= \lambda_{s}\rho_{C_i}+(1-\lambda_s)\widehat{Z}\rho_{C_i}\widehat{Z}^\dag, \end{align}
where 
\begin{align}
-\frac{1}{3}\leq \lambda_l\leq 1,\qquad\qquad 0\leq\lambda_s\leq 1,
\end{align} 
$\widehat{Z}$ is a Pauli-$Z$ operator, and $\rho$ is an arbitrary input state.

This implies, the MDI-QKD capacities for respective MDI-QKD settings, i.e., with depolarizing channels and dephasing channels, to be upper bounded as (see following subsections for proofs and plots for some values of $q$):
\begin{enumerate}
    \item MDI-QKD with depolarizing channels $\mc{D}^{l}$~\eqref{eq:dl}, where $-\frac{1}{3}\leq \lambda_l\leq 1$, 
    \begin{align} \widetilde{P}_{\operatorname{LOCC}}(\mc{N}^{\text{MDI},\mc{D}^{l}})\leq q\left(1-h_2\left(\frac{3}{4}\lambda_l^2+\frac{1}{4}\right)\right)
    \end{align}
    for $\frac{1}{\sqrt{3}}<\lambda_l\leq 1$, and $0$ otherwise.
    \item MDI-QKD with dephasing channels $\mc{D}^s$~\eqref{eq:ds}, where $0\leq\lambda_s\leq 1$,
      \begin{align} & \widetilde{P}_{\operatorname{LOCC}}(\mc{N}^{\text{MDI},\mc{D}^{s}})\leq \nonumber\\
& \left\{
\begin{array}{ll}
q(1- h_2({1\over 2}p_-(\lambda_s)) & \textnormal{for}\quad \lambda_s > \frac{3}{4},\\
0 & \textnormal{for}\quad \frac{1}{4}\leq \lambda_s\leq \frac{3}{4},\\
q(1- h_2({1\over 2}p_-(1-\lambda_s)) & \textnormal{for}\quad \lambda_s< \frac{1}{4},\\
\end{array}
\right.
\end{align}
where $p_-(x)\coloneqq 4x^2-3x +1$.
    \end{enumerate}

MDI-QKD with dephasing channels $\mc{D}^s$~\eqref{eq:ds}, where $0\leq\lambda_s\leq 1$,
      \begin{align} & \widetilde{P}_{\operatorname{LOCC}}(\mc{N}^{\text{MDI},\mc{D}^{s}})\leq \nonumber\\
& \left\{
\begin{array}{ll}
q(1- h_2({1\over 2}p_-(\lambda_s)) & \textnormal{for}\quad \lambda_s > \frac{3}{4},\\
0 & \textnormal{for}\quad \frac{1}{4}\leq \lambda_s\leq \frac{3}{4},\\
q(1- h_2({1\over 2}p_-(1-\lambda_s)) & \textnormal{for}\quad \lambda_s< \frac{1}{4},\\
\end{array}
\right.
\end{align}
where $p_-(x)\coloneqq 4x^2-3x +1$.

We then observe that
\begin{align}
    & E_R(\rho_{AB|00}^{out}) \nonumber\\
   &\quad = E_R\Bigg(\bigg(\sum_{i=0}^3 \lambda_l^2 \op{\psi_i}_{AB} + (1-\lambda_l^2){\bbm{1}_{AB} \over 4}\bigg)\otimes \nonumber\\ &\qquad\qquad \qquad\qquad  \op{ii}_{I_AI_B} \otimes \op{00}_{I'_AI'_B}\Bigg),
\end{align}
where $\op{\psi_i}$ are the Bell states.

In our case $p_{max} =\lambda_l^2 + (1-\lambda_l^2)/4 $. Thus, via convexity and Eq.~\eqref{eq:qbound} we obtain that
\begin{equation}
E_R(\rho_{AB}^{out}) \leq q\left(1- h_2(\lambda_l^2 + {(1-\lambda_l^2)\over 4})\right)
\end{equation}
for $\lambda_l^2 + (1-\lambda_l^2)/4 > 1/2$, and $0$ otherwise. The condition $\lambda_l^2 + (1-\lambda_l^2)/4 > 1/2$ on $\lambda_l$ is equivalent to $\lambda_l > {1\over \sqrt{3}}$.

Thus, keeping the structure of the Choi state of the dephasing channel in mind, we arrive at the following bound:

