q(1- h_2({1\over 2}p_-(\lambda_s)) & \textnormal{for}\quad \lambda_s > \frac{3}{4},\\
0 & \textnormal{for}\quad \frac{1}{4}\leq \lambda_s\leq \frac{3}{4},\\
q(1- h_2({1\over 2}p_-(1-\lambda_s)) & \textnormal{for}\quad \lambda_s< \frac{1}{4},\\
\end{array}
\right.
\end{equation}
where $p_-(x)\coloneqq 4x^2-3x +1$.

